// Package plgimpl is the run-time support of the fast paths `plg gen` generates: adapters that call plugins
// through typed code, without reflect.MakeFunc, and encoders and decoders specialized to a contract's types,
// without reflection.
//
// It is not meant to be used directly. Its API follows plg gen's output: code generated by one plg version
// needs that version's plgimpl, so rerun `go generate` after upgrading plg. The functions encode and decode
// exactly as the reflective codec plg falls back on, failing with the same errors.
package plgimpl

import (
	"context"
	"fmt"
	"time"
	"unsafe"

	"github.com/heynemann/go-plg/internal/wire"
)

// Reader decodes a call's results, in order.
type Reader = wire.Reader

// Call is one call of an interface method, generated per method: its arguments, which it encodes, and its
// results, which it decodes once the plugin answers. A Call is used by one goroutine.
type Call interface {
	// AppendArgs appends the encoding of the arguments after the context.
	AppendArgs(b []byte) ([]byte, error)
	// DecodeResults decodes the results before the error. It writes into zero values only.
	DecodeResults(r *Reader) error
}

// Invoker calls the plugin a generated adapter serves. plg implements it; it is safe for concurrent use.
type Invoker interface {
	// Invoke calls the interface method with the given index (reflect's method order) with ctx, as plg's
	// generic adapter does, and returns the call's error: call holds the results only when it is nil.
	Invoke(ctx context.Context, method int, call Call) error
}

// Integer, unsigned integer and float types the encoding supports, named ones included.
type (
	Signed interface {
		~int | ~int8 | ~int16 | ~int32 | ~int64
	}
	Unsigned interface {
		~uint | ~uint8 | ~uint16 | ~uint32 | ~uint64
	}
)

// The predeclared types generated code names, for a contract package that redeclares their names: its
// generated code cannot refer to the predeclared types directly. Every type the encoding supports has one,
// since the fields of a struct from another package can have any of them.
type (
	Bool    = bool
	Byte    = byte
	Error   = error
	Float32 = float32
	Float64 = float64
	Int     = int
	Int8    = int8
	Int16   = int16
	Int32   = int32
	Int64   = int64
	Rune    = rune
	String  = string
	Uint    = uint
	Uint8   = uint8
	Uint16  = uint16
	Uint32  = uint32
	Uint64  = uint64
)

// AppendBool appends a bool.
//
//nolint:revive // flag-parameter: v is the encoded value, not a control flag
func AppendBool(b []byte, v bool) []byte { return wire.AppendBool(b, v) }

// AppendInt appends an integer, failing beyond ±2^53.
func AppendInt(b []byte, v int64) ([]byte, error) { return wire.AppendInt53(b, v) }

// AppendUint appends an unsigned integer, failing beyond 2^53.
func AppendUint(b []byte, v uint64) ([]byte, error) { return wire.AppendUint53(b, v) }

// AppendFloat appends a float.
func AppendFloat(b []byte, v float64) []byte { return wire.AppendFloat(b, v) }

// AppendString appends a string.
func AppendString(b []byte, v string) ([]byte, error) { return wire.AppendString(b, v) }

// AppendBytes appends a byte slice; nil stays distinct from empty.
func AppendBytes(b, v []byte) ([]byte, error) { return wire.AppendBytes(b, v) }

// AppendByteSlice appends a slice of a named uint8 type as a byte slice.
func AppendByteSlice[S ~[]E, E ~uint8](b []byte, v S) ([]byte, error) {
	if v == nil {
		return wire.AppendNil(b), nil
	}

	b, err := wire.AppendLen(b, len(v), 0)
	if err != nil {
		return b, err
	}

	for _, c := range v {
		b = append(b, byte(c))
	}

	return b, nil
}

// AppendTime appends an instant.
func AppendTime(b []byte, t time.Time) ([]byte, error) { return wire.AppendTime(b, t) }

// AppendNil appends a nil slice or map.
func AppendNil(b []byte) []byte { return wire.AppendNil(b) }

// AppendLen appends the length of a non-nil slice or map nested depth levels deep.
func AppendLen(b []byte, n, depth int) ([]byte, error) { return wire.AppendLen(b, n, depth) }

// Deeper fails when a pointer or struct is nested too deeply.
func Deeper(depth int) error { return wire.Deeper(depth) }

// ReadBool decodes a bool.
func ReadBool[T ~bool](r *Reader) (T, error) {
	v, err := r.Bool()

	return T(v), err
}

// ReadInt decodes an integer of type T, named typeName as reflect names it.
func ReadInt[T Signed](r *Reader, typeName string) (T, error) {
	num, err := r.Int53()
	if err != nil {
		return 0, err
	}

	if int64(T(num)) != num {
		return 0, wire.Overflow(num, typeName)
	}

	return T(num), nil
}

// ReadUint decodes an unsigned integer of type T, named typeName as reflect names it.
func ReadUint[T Unsigned](r *Reader, typeName string) (T, error) {
	num, err := r.Uint53()
	if err != nil {
		return 0, err
	}

	if uint64(T(num)) != num {
		return 0, wire.Overflow(num, typeName)
	}

	return T(num), nil
}

// ReadFloat32 decodes a float of the float32 kind T, named typeName as reflect names it.
func ReadFloat32[T ~float32](r *Reader, typeName string) (T, error) {
	num, err := r.Float64()
	if err != nil {
		return 0, err
	}

	if wire.OverflowsFloat32(num) {
		return 0, wire.Overflow(num, typeName)
	}

	return T(num), nil
}

// ReadFloat64 decodes a float of the float64 kind T.
func ReadFloat64[T ~float64](r *Reader) (T, error) {
	num, err := r.Float64()

	return T(num), err
}

// ReadString decodes a string.
func ReadString[T ~string](r *Reader) (T, error) {
	s, err := r.Text()

	return T(s), err
}

// ReadBytes decodes a byte slice.
func ReadBytes[S ~[]byte](r *Reader) (S, error) {
	data, err := r.Bytes()

	return S(data), err
}

// ReadByteSlice decodes a byte slice into a slice of a named uint8 type.
func ReadByteSlice[S ~[]E, E ~uint8](r *Reader) (S, error) {
	data, err := r.Bytes()
	if err != nil || data == nil {
		return nil, err
	}

	v := make(S, len(data))
	for i, c := range data {
		v[i] = E(c)
	}

	return v, nil
}

// ReadTime decodes an instant, in UTC.
func ReadTime(r *Reader) (time.Time, error) { return r.Time() }

// ReadSliceLen decodes the length of the slice *v nested depth levels deep whose elements encode in at least
// minSize bytes: -1 for nil. It claims the elements' memory from r's bound (see wire.AllocationRatio); v only
// tells the type.
func ReadSliceLen[S ~[]E, E any](r *Reader, _ *S, depth, minSize int) (int, error) {
	return r.SliceLen(depth, minSize, sizeOf[E]())
}

// ReadMapLen decodes the length of the map *v nested depth levels deep whose values encode in at least minSize
// bytes: -1 for nil. It claims the entries' memory from r's bound; v only tells the type.
func ReadMapLen[M ~map[K]V, K ~string, V any](r *Reader, _ *M, depth, minSize int) (int, error) {
	return r.MapLen(depth, minSize, sizeOf[K]()+sizeOf[V]())
}

// ReadKey decodes a key of the map type M; m only tells its type.
func ReadKey[M ~map[K]V, K ~string, V any](r *Reader, _ M) (K, error) {
	s, err := r.Text()

	return K(s), err
}

// ReadPresent decodes whether the pointer *v nested depth levels deep is non-nil, claiming its target's memory
// from r's bound when it is; v only tells the type.
func ReadPresent[P ~*E, E any](r *Reader, _ *P, depth int) (bool, error) {
	return r.Present(depth, sizeOf[E]())
}

// sizeOf is the memory a value of type T takes, as reflect's Type.Size reports it to the reflective codec.
func sizeOf[T any]() int {
	var v T

	return int(unsafe.Sizeof(v))
}

// DuplicateKeys is the error of a map that repeats a key.
func DuplicateKeys() error { return wire.DuplicateKeys() }

// AtField locates err in the struct field goName.
func AtField(err error, goName string) error { return wire.AtField(err, goName) }

// AtIndex locates err at index i of a slice.
func AtIndex(err error, i int) error { return wire.AtIndex(err, i) }

// AtKey locates err at key k of a map.
func AtKey(err error, k string) error { return wire.AtKey(err, k) }

// Param locates err in parameter k (the first after the context is 1).
func Param(err error, k int) error { return fmt.Errorf("parameter %d: %w", k, err) }

// Result locates err in result k (from 0).
func Result(err error, k int) error { return fmt.Errorf("result %d: %w", k, err) }
